import app from 'flarum/admin/app';
import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import Form from 'flarum/common/components/Form';
import Switch from 'flarum/common/components/Switch';
import Alert from 'flarum/common/components/Alert';
import Select from 'flarum/common/components/Select';
import isExtensionEnabled from 'flarum/admin/utils/isExtensionEnabled';
import UploadImageButton from 'flarum/common/components/UploadImageButton';
import LookControls from '../../common/components/LookControls';
import { accents, contrast, hex } from '../../common/color';
import { BUILT_IN, hexList, payload, sanitize, SECTIONS } from '../../common/look';
import { parseJson } from '../../common/safe';
const t = (key, params) => app.translator.trans(`ernestdefoe-skylight.admin.${key}`, params);
const SLOTS = ['img1', 'img2', 'img3', 'img4'];
const KEYS = {
  defaults: 'ernestdefoe-skylight.defaults',
  sections: 'ernestdefoe-skylight.sections',
  presets: 'ernestdefoe-skylight.presets',
  presetsReplace: 'ernestdefoe-skylight.presets_replace',
  multiTag: 'ernestdefoe-skylight.multi_tag_color',
  thumbnail: 'ernestdefoe-skylight.card_thumbnail'
};
const SIZES = ['off', 'small', 'medium', 'large'];

/**
 * Skylight's settings: the forum's defaults (the same controls members get
 * with Personalize), which sections members may change, the extra accent
 * presets, the backgrounds and the two switches.
 */
export default class SkylightPage extends ExtensionPage {
  content(vnode) {
    return m("div", {
      className: "ExtensionPage-settings SkylightAdmin"
    }, m("div", {
      className: "container"
    }, payload().blockedByBespoke && m(Alert, {
      type: "warning",
      dismissible: false,
      className: "SkylightAdmin-alert"
    }, t('bespoke_notice')), m(Form, null, m("div", {
      className: "SkylightAdmin-grid"
    }, this.defaultsCard(), m("div", {
      className: "SkylightAdmin-column"
    }, this.sectionsCard(), this.presetsCard(), this.backgroundsCard(), isExtensionEnabled('fof-discussion-thumbnail') && this.thumbnailCard(), this.card('more.title', null, [this.switch('ernestdefoe-skylight.tag_accent', 'more.tag_accent'), this.multiTagControl(), this.switch('ernestdefoe-skylight.auto_solid', 'more.auto_solid')]))), m("div", {
      className: "Form-group Form-controls"
    }, this.submitButton()))));
  }
  card(title, help, body) {
    return m("section", {
      className: "SkylightAdmin-card"
    }, m("h3", null, t(title)), help && m("p", {
      className: "helpText"
    }, t(help)), body);
  }
  defaultsCard() {
    const defaults = this.defaults();
    return this.card('defaults.title', 'defaults.help', [m(LookControls, {
      look: defaults,
      sections: Object.keys(SECTIONS),
      readability: false,
      presets: hexList(this.setting(KEYS.presets)()),
      presetsReplace: this.on(KEYS.presetsReplace),
      backgrounds: payload().backgrounds,
      onchange: (key, value) => this.setDefault(key, value)
    }), this.contrastReadout(defaults)]);
  }
  sectionsCard() {
    const open = this.openSections();
    return this.card('studio.title', 'studio.help', [m("div", {
      className: "SkylightAdmin-checks"
    }, Object.keys(SECTIONS).map(section => m(Switch, {
      state: open.includes(section),
      onchange: on => this.toggleSection(section, on)
    }, app.translator.trans(`ernestdefoe-skylight.lib.sections.${section}`)))), m("p", {
      className: "helpText"
    }, t('studio.readability_always')), m("p", {
      className: "helpText"
    }, t('studio.permission'))]);
  }
  presetsCard() {
    const presets = this.setting(KEYS.presets);
    return this.card('presets.title', 'presets.help', [m("input", {
      className: "FormControl",
      placeholder: "#1f8a6f, #9a4fb0",
      value: hexList(presets()).join(', '),
      onchange: e => presets(JSON.stringify(hexList(e.target.value).slice(0, 6)))
    }), this.switch(KEYS.presetsReplace, 'presets.replace')]);
  }
  thumbnailCard() {
    const size = this.setting(KEYS.thumbnail);
    const options = {};
    SIZES.forEach(v => options[v] = t(`thumbnail.${v}`));
    return this.card('thumbnail.title', 'thumbnail.help', m(Select, {
      options: options,
      value: SIZES.includes(size()) ? size() : 'off',
      onchange: size
    }));
  }

  /** One color for a discussion with several colored tags: off, or a color. */
  multiTagControl() {
    const value = this.setting(KEYS.multiTag);
    const color = hex(value());
    return m("div", {
      className: "SkylightAdmin-multiTag"
    }, m(Switch, {
      state: !!color,
      onchange: on => value(on ? '#6b7787' : '')
    }, m("span", null, t('more.multi_tag'), m("small", {
      className: "helpText"
    }, t('more.multi_tag_help')))), color && m("input", {
      type: "color",
      className: "SkylightAdmin-color",
      value: color,
      "aria-label": t('more.multi_tag'),
      oninput: e => value(hex(e.target.value) || '')
    }));
  }
  on(key) {
    const v = this.setting(key)();
    return !!Number(v) || v === 'true';
  }
  backgroundsCard() {
    const urls = payload().backgrounds;
    return this.card('backgrounds.title', 'backgrounds.help', m("div", {
      className: "SkylightAdmin-uploads"
    }, SLOTS.map(slot => m(UploadImageButton, {
      name: "skylight-bg",
      routePath: `skylight/backgrounds/${slot}`,
      value: app.data.settings[`ernestdefoe-skylight.bg_${slot}`],
      url: urls[slot]
    }))));
  }
  switch(key, label) {
    const value = this.setting(key);
    return m(Switch, {
      state: this.on(key),
      onchange: on => value(on ? '1' : '0')
    }, m("span", null, t(label), m("small", {
      className: "helpText"
    }, t(`${label}_help`))));
  }
  defaults() {
    return {
      ...BUILT_IN,
      ...sanitize(parseJson(this.setting(KEYS.defaults)(), {}))
    };
  }
  setDefault(key, value) {
    // Store only what differs from the built-in look.
    const diff = {};
    for (const [k, v] of Object.entries(sanitize({
      ...this.defaults(),
      [key]: value
    }))) if (BUILT_IN[k] !== v) diff[k] = v;
    this.setting(KEYS.defaults)(JSON.stringify(diff));
  }
  openSections() {
    const list = parseJson(this.setting(KEYS.sections)(), null);
    return Array.isArray(list) ? list : Object.keys(SECTIONS);
  }
  toggleSection(section, on) {
    const list = this.openSections().filter(s => s !== section);
    if (on) list.push(section);
    this.setting(KEYS.sections)(JSON.stringify(Object.keys(SECTIONS).filter(s => list.includes(s))));
  }
  contrastReadout(look) {
    const c = accents(look.accent);
    const ratio = n => n.toFixed(1) + ' : 1';
    return m("p", {
      className: "SkylightAdmin-contrast"
    }, m("span", null, t('defaults.contrast_light', {
      ratio: ratio(contrast(c.light, '#f4f7fa'))
    })), m("span", null, t('defaults.contrast_dark', {
      ratio: ratio(contrast(c.dark, '#161c27'))
    })), c.nudged && m("span", {
      className: "nudged"
    }, app.translator.trans('ernestdefoe-skylight.lib.help.nudged')));
  }
}
flarum.reg.add('ernestdefoe-skylight', 'admin/components/SkylightPage', SkylightPage);